use verus::prelude::*;

/// Given `n` units of resource‐1 and `m` units of resource‐2,
/// we first form as many “mixed” groups (1 of resource‐1 + 2 of resource‐2)
/// as possible, then with the remaining resource‐2 we form “pure” groups
/// (4 of resource‐2).  Return the total number of groups formed.
///
/// We only admit nonnegative inputs.
///
/// Specification:
///   requires: n >= 0, m >= 0
///   ensures: the result equals
///            let mixed = min(n, m/2);
///            let rem   = m - 2*mixed;
///            mixed + rem/4
#[requires(n >= 0)]
#[requires(m >= 0)]
#[ensures({
    // characterize the same intermediate values as the implementation
    let mixed = if n <= m/2 { n } else { m/2 };
    let rem   = m - mixed * 2;
    result == mixed + rem / 4
})]
fn solve(n: i8, m: i8) -> i8 {
    // Form as many mixed groups as possible (1 unit of first, 2 units of second)
    let mixed = n.min(m / 2);
    // Subtract the second-resource units used by mixed groups
    let remaining = m - mixed * 2;
    // Form pure groups with remaining second-resource units (4 units each)
    let pure = remaining / 4;
    mixed + pure
}

